package com.sirin5dwaves.client;
import com.mojang.blaze3d.vertex.*; import net.minecraft.client.Minecraft; import net.minecraft.client.renderer.*; import net.minecraft.core.BlockPos; import net.minecraftforge.api.distmarker.Dist; import net.minecraftforge.client.event.RenderLevelStageEvent; import net.minecraftforge.eventbus.api.SubscribeEvent; import net.minecraftforge.fml.common.Mod;
@Mod.EventBusSubscriber(modid="sirin5dwaves",value=Dist.CLIENT,bus=Mod.EventBusSubscriber.Bus.FORGE) public final class ClientEvents { @SubscribeEvent public static void render(RenderLevelStageEvent e){if(e.getStage()!=RenderLevelStageEvent.Stage.AFTER_TRANSLUCENT_BLOCKS)return; Minecraft mc=Minecraft.getInstance(); if(mc.level==null||mc.player==null)return; PoseStack pose=e.getPoseStack(); pose.pushPose(); var cam=mc.gameRenderer.getMainCamera().getPosition(); pose.translate(-cam.x,-cam.y,-cam.z); MultiBufferSource.BufferSource buffers=mc.renderBuffers().bufferSource(); VertexConsumer vc=buffers.getBuffer(RenderType.translucent()); double t=(mc.level.getGameTime()+e.getPartialTick())*.05; int r=3,y=mc.player.getBlockY(); for(int z=mc.player.getBlockZ()-r;z<=mc.player.getBlockZ()+r;z++)for(int x=mc.player.getBlockX()-r;x<=mc.player.getBlockX()+r;x++){BlockPos pos=new BlockPos(x,y,z); if(!mc.level.getFluidState(pos).isEmpty()){pose.pushPose();pose.translate(x+.5,y+1.0,z+.5);WaveMesh.emit(vc,pose.last(),8,1.0f,t+x*.13+z*.17);pose.popPose();}} buffers.endBatch(RenderType.translucent());pose.popPose();}}
